// Safety net: never delete financial or important emails
const SAFE_SUBJECTS = [
  'statement', 'invoice', 'receipt', 'payment received', 'payment confirmation',
  'tax document', 'tax form', '1099', 'w-2', 'insurance', 'medical', 'appointment',
  'verification', 'security alert', 'password', 'action required', 'court',
  'legal notice', 'your account has', 'account update'
];
const SAFE_DOMAINS = [
  'irs.gov', 'ssa.gov', 'bankofamerica', 'chase.com', 'wellsfargo',
  'paypal.com', 'venmo.com', 'usaa.com', 'capitalone', 'discover.com',
  'txdmv.gov', 'hcad.org', 'amex.com', 'americanexpress.com'
];

const items = $input.all().filter(item => {
  const headers = item.json.payload?.headers || [];
  const getH = n => (headers.find(h => h.name.toLowerCase() === n.toLowerCase()) || {}).value || '';
  const from = getH('From').toLowerCase();
  const subject = getH('Subject').toLowerCase();
  const isSafe = SAFE_SUBJECTS.some(s => subject.includes(s))
               || SAFE_DOMAINS.some(d => from.includes(d));
  return !isSafe;
});

// Store count and preview in static data for the summary node
const sd = $getWorkflowStaticData('global');
sd.deleteCount = items.length;
sd.deleteList = items.slice(0, 20).map(item => {
  const headers = item.json.payload?.headers || [];
  const getH = n => (headers.find(h => h.name.toLowerCase() === n.toLowerCase()) || {}).value || '';
  return { from: getH('From'), subject: getH('Subject') };
});

return items;

