const sd = $getWorkflowStaticData('global');
const deleted = sd.deleteCount || 0;
const archived = sd.archiveCount || 0;
const deletedList = sd.deleteList || [];
const archivedList = sd.archiveList || [];

// Clear for next run
sd.deleteCount = 0;
sd.archiveCount = 0;
sd.deleteList = [];
sd.archiveList = [];

const today = new Date().toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

let body = `Hi Kareesa,\n\nYour daily Yahoo inbox cleanup finished. Here is what was done on ${today}.\n\n`;

body += `SUMMARY\n`;
body += `-------\n`;
body += `Moved to Trash (promo emails 30+ days old): ${deleted}\n`;
body += `Archived (recent promo emails):             ${archived}\n`;
body += `Total cleaned: ${deleted + archived}\n\n`;

if (deleted === 0 && archived === 0) {
  body += `Nothing to clean today. Your Yahoo inbox is already tidy.\n\n`;
}

if (deletedList.length > 0) {
  body += `MOVED TO TRASH\n`;
  body += `--------------\n`;
  deletedList.forEach(e => {
    const from = (e.from || '').substring(0, 38);
    const subj = (e.subject || '').substring(0, 48);
    body += `  ${from.padEnd(38)}  ${subj}\n`;
  });
  if (deleted > 20) body += `  ...and ${deleted - 20} more\n`;
  body += '\n';
}

if (archivedList.length > 0) {
  body += `ARCHIVED (out of inbox, still searchable)\n`;
  body += `-----------------------------------------\n`;
  archivedList.forEach(e => {
    const from = (e.from || '').substring(0, 38);
    const subj = (e.subject || '').substring(0, 48);
    body += `  ${from.padEnd(38)}  ${subj}\n`;
  });
  if (archived > 20) body += `  ...and ${archived - 20} more\n`;
  body += '\n';
}

body += `WHAT WAS LEFT UNTOUCHED\n`;
body += `-----------------------\n`;
body += `Emails from real people (no List-Unsubscribe header) were never touched.\n`;
body += `Financial emails (PayPal, bank statements, receipts, tax forms) were skipped.\n`;
body += `Trashed emails stay in Gmail Trash for 30 days before permanent deletion.\n\n`;
body += `Search "in:trash" in Gmail if you need to recover anything.\n\n`;
body += `-- AICC Yahoo Cleanup Bot`;

return [{ json: {
  subject: `Yahoo Cleanup Done: ${deleted} deleted, ${archived} archived (${today})`,
  body
} }];
